{
  "technical_and_design_decisions": [
    "Target Java 17+ and modern Spring Boot / Spring Cloud Data Flow and Spring Cloud Stream architectural patterns.",
    "Utilize Spring Shell framework for implementing modular Hadoop CLI commands in the interactive shell.",
    "Implement HDFS Sink as a Spring Cloud Stream application using standard Apache Hadoop Client libraries.",
    "Design Composed Job Repository using relational metadata tables managed via Spring Data JPA / Spring Batch metadata standards.",
    "Implement Composed Job Orchestration via a dedicated Task Launcher component parsing job DAG/workflow DSLs.",
    "Use Spring Expression Language (SpEL) for dynamic message header and property evaluation in Spring Cloud Stream bindings.",
    "Migrate legacy Spring XD modules (JDBC Sink and Kafka Source) to standalone Spring Cloud Stream standalone application starters."
  ],
  "assumptions": [
    "A local or containerized Hadoop/HDFS environment is available for integration testing.",
    "Development work will be performed by a single developer with experience in Spring Boot, Spring Cloud Stream, and Spring Cloud Data Flow.",
    "Non-functional infrastructure (CI/CD pipelines, repository hosting) is already established."
  ],
  "activities": [
    {
      "activity_id": "ACT-1",
      "activity_name": "Project Environment Setup & Architecture Analysis",
      "activity_description": "Initial setup of multi-module build configuration, dependency management, and analysis of legacy Spring XD components to be migrated.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "ACT-2",
      "activity_name": "U1: HDFS Sink Module Implementation & Registry Integration",
      "activity_description": "Develop the HDFS sink Spring Cloud Stream application, supporting file writing, rolling policies, configuration options, and module registration.",
      "most_likely_effort": 20
    },
    {
      "activity_id": "ACT-3",
      "activity_name": "U2: Hadoop Commands Support in Shell",
      "activity_description": "Implement Spring Shell commands for standard HDFS operations (ls, cat, copy, rm, mkdir) communicating with Hadoop FileSystem APIs.",
      "most_likely_effort": 18
    },
    {
      "activity_id": "ACT-4",
      "activity_name": "U3: Composed Jobs Repository Options Spike & Design",
      "activity_description": "Investigate and prototype storage options (RDBMS vs Key-Value) for persisting composed job definitions, DSL representations, and execution states.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "ACT-5",
      "activity_name": "U4: Composed Jobs Orchestration Engine",
      "activity_description": "Develop the execution graph parser and orchestrator to trigger sequential/parallel task launches for composed workflows.",
      "most_likely_effort": 36
    },
    {
      "activity_id": "ACT-6",
      "activity_name": "U5: Isolated Shell Command Testing Framework",
      "activity_description": "Create a mock-based test harness for testing Spring Shell commands in isolation without spawning full end-to-end stream runtime environments.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "ACT-7",
      "activity_name": "U6: Expression-Based Message Property Binding Engine",
      "activity_description": "Implement SpEL evaluation support in Spring Cloud Stream bindings to extract and map dynamic payload/header attributes to module properties.",
      "most_likely_effort": 28
    },
    {
      "activity_id": "ACT-8",
      "activity_name": "U7: JDBC Sink Module Migration from Spring XD",
      "activity_description": "Refactor legacy Spring XD JDBC sink into a modern Spring Cloud Stream application with auto-configuration and integration tests.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "ACT-9",
      "activity_name": "U8: Kafka Source Module Migration from Spring XD",
      "activity_description": "Port legacy Spring XD Kafka source into a Spring Cloud Stream application utilizing modern Spring for Apache Kafka binder capabilities.",
      "most_likely_effort": 18
    },
    {
      "activity_id": "ACT-10",
      "activity_name": "Integration Testing, Verification & Documentation",
      "activity_description": "Perform overall integration testing across shell commands, modules, and orchestration engine; write user documentation and deployment guides.",
      "most_likely_effort": 20
    }
  ],
  "reported_total": {
    "most_likely_effort": 208
  }
}
